import express from "express";
import path from "path";
import cors from "cors";
import dotenv from "dotenv";
import { createServer as createViteServer } from "vite";
import { SessionManager } from "../mach6-core/dist/sessions/manager";

// Load environment variables
dotenv.config();

const app = express();
const port = 3001;
const sessionManager = new SessionManager();

app.use(cors());
app.use(express.json());

// --- Session Endpoints ---

app.get("/api/sessions", (req, res) => {
  try {
    const sessions = sessionManager.list();
    res.json(sessions);
  } catch (e) {
    res.status(500).json({ error: "Failed to list sessions" });
  }
});

app.get("/api/sessions/:id", (req, res) => {
  try {
    const session = sessionManager.load(req.params.id);
    if (!session) return res.status(404).json({ error: "Session not found" });
    res.json(session);
  } catch (e) {
    res.status(500).json({ error: "Failed to load session" });
  }
});

app.post("/api/sessions", (req, res) => {
  try {
    const { label, provider, model } = req.body;
    const id = `sess_${Date.now()}`;
    const session = sessionManager.create(id, { label, provider, model });
    res.json(session);
  } catch (e) {
    res.status(500).json({ error: "Failed to create session" });
  }
});

app.delete("/api/sessions/:id", (req, res) => {
  try {
    const success = sessionManager.delete(req.params.id);
    res.json({ success });
  } catch (e) {
    res.status(500).json({ error: "Failed to delete session" });
  }
});

// --- Chat Endpoint ---

app.post("/api/chat", async (req, res) => {
  const { sessionId, message } = req.body;
  if (!sessionId || !message) {
    return res.status(400).json({ error: "Missing sessionId or message" });
  }

  try {
    let session = sessionManager.load(sessionId);
    if (!session) {
      return res.status(404).json({ error: "Session not found" });
    }

    // Add user message to history
    session.messages.push({ role: "user", content: message });
    sessionManager.save(session);

    // PROXY TO MACH6 GATEWAY
    const response = await fetch("http://127.0.0.1:3000/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        sessionId,
        messages: session.messages,
      }),
    });

    const data = await response.json();
    
    // Add assistant response to history
    session.messages.push({ 
      role: "assistant", 
      content: data.content 
    });
    sessionManager.save(session);

    res.json({ content: data.content });
  } catch (e) {
    console.error("[Symbiote Server] Chat Error:", e);
    res.status(500).json({ error: "Gateway communication failed" });
  }
});

// --- Vite Integration for Development ---
async function startServer() {
  const vite = await createViteServer({
    server: { middlewareMode: true },
    appType: 'custom',
  });

  app.use(vite.middlewares);

  app.use((req, res, next) => {
    const url = req.originalUrl;
    if (url.startsWith('/@vite/client')) {
      return next();
    }
    // Serve index.html for all non-API routes
    res.sendFile(path.resolve(__dirname, 'index.html'));
  });

  app.listen(port, () => {
    console.log(`Symbiote Bridge running at http://localhost:${port}`);
  });
}

startServer();
